#include <vector>
#include <queue>

class Solution {
public:
    bool canReach(std::vector<int>& arr, int start) {
        int n = arr.size();
        std::vector<bool> visited(n, false);
        std::queue<int> q;
        q.push(start);
        visited[start] = true;
        while (!q.empty()) {
            int cur = q.front();
            q.pop();
            if (arr[cur] == 0) return true;
            for (int nxt : {cur + arr[cur], cur - arr[cur]}) {
                if (nxt >= 0 && nxt < n && !visited[nxt]) {
                    visited[nxt] = true;
                    q.push(nxt);
                }
            }
        }
        return false;
    }
};

import java.util.*;

class Solution {
    public boolean canReach(int[] arr, int start) {
        int n = arr.length;
        boolean[] visited = new boolean[n];
        Queue<Integer> q = new LinkedList<>();
        q.offer(start);
        visited[start] = true;
        while (!q.isEmpty()) {
            int cur = q.poll();
            if (arr[cur] == 0) return true;
            int[] nxts = {cur + arr[cur], cur - arr[cur]};
            for (int nxt : nxts) {
                if (nxt >= 0 && nxt < n && !visited[nxt]) {
                    visited[nxt] = true;
                    q.offer(nxt);
                }
            }
        }
        return false;
    }
}

